<?php
declare(strict_types=1);
require_once __DIR__.'/_common.php';
$sponsorId=(int)($user['id']??0);
$ready=sponsor_table_exists($conn,'sponsor_agreements')&&sponsor_table_exists($conn,'sponsor_agreement_programmes')&&sponsor_table_exists($conn,'sponsor_agreement_deliverables')&&sponsor_table_exists($conn,'sponsor_programme_access');
$agreements=[];$selected=null;$deliverables=[];$error='';
if($ready){
 $sql="SELECT a.id,a.agreement_ref,a.title,a.summary,a.agreement_value,a.currency,a.status,a.signed_on,a.start_date,a.end_date,a.created_at,p.name programme_name FROM sponsor_agreements a JOIN sponsor_agreement_programmes ap ON ap.agreement_id=a.id JOIN sponsor_programme_access spa ON spa.programme_id=ap.programme_id AND spa.sponsor_user_id=? AND spa.access_status='active' JOIN programmes p ON p.id=ap.programme_id WHERE a.status<>'draft' GROUP BY a.id ORDER BY a.created_at DESC";
 $st=$conn->prepare($sql);if($st){$st->bind_param('i',$sponsorId);$st->execute();$rs=$st->get_result();$agreements=$rs?$rs->fetch_all(MYSQLI_ASSOC):[];$st->close();}
 $id=(int)($_GET['id']??0);if($id>0){foreach($agreements as $a){if((int)$a['id']===$id){$selected=$a;break;}}
  if($selected){$st=$conn->prepare("SELECT d.id,d.deliverable_ref,d.title,d.description,d.category,d.due_date,d.status,d.progress_percent,d.completed_at,d.verified_at,d.verification_status,d.evidence_reference,d.management_notes FROM sponsor_agreement_deliverables d WHERE d.agreement_id=? ORDER BY COALESCE(d.due_date,'9999-12-31'),d.id");if($st){$st->bind_param('i',$id);$st->execute();$rs=$st->get_result();$deliverables=$rs?$rs->fetch_all(MYSQLI_ASSOC):[];$st->close();}}
 }
}
sponsor_header('Sponsorship agreements & deliverables','agreements','Review agreed sponsorship obligations, milestone progress and outstanding commitments.');
?>
<style>
.sa-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:20px}.sa-metric,.sa-card,.sa-panel{background:var(--surface);border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow)}.sa-metric{padding:17px}.sa-metric small{display:block;color:var(--muted);font-weight:700}.sa-metric strong{display:block;font-size:25px;margin-top:7px}.sa-layout{display:grid;grid-template-columns:minmax(260px,.85fr) minmax(0,1.7fr);gap:16px}.sa-list{display:grid;gap:10px;padding:14px}.sa-agreement{display:block;text-decoration:none;color:var(--text);padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--surface2)}.sa-agreement.active{border-color:var(--primary);box-shadow:inset 3px 0 var(--primary)}.sa-agreement strong{display:block;font-size:13px}.sa-agreement small{display:block;color:var(--muted);margin-top:5px}.sa-head{padding:18px 20px;border-bottom:1px solid var(--line)}.sa-body{padding:18px 20px}.sa-pills{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.sa-pill{border-radius:30px;padding:5px 9px;background:var(--surface2);color:var(--muted);font-size:10px;font-weight:800}.sa-status{color:var(--primary)}.sa-table{width:100%;border-collapse:collapse;min-width:700px}.sa-table th,.sa-table td{padding:12px 13px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;font-size:12px}.sa-table th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em}.sa-progress{height:7px;background:var(--surface2);border-radius:20px;overflow:hidden;min-width:85px;margin-top:5px}.sa-progress span{display:block;height:100%;background:var(--primary);border-radius:20px}.sa-empty,.sa-note{padding:18px;border:1px dashed var(--line);border-radius:12px;color:var(--muted);background:var(--surface2)}.sa-value{font-weight:800;font-variant-numeric:tabular-nums}.sa-back{display:inline-flex;margin-bottom:12px;color:var(--primary);font-weight:700;text-decoration:none}@media(max-width:900px){.sa-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.sa-layout{grid-template-columns:1fr}}@media(max-width:520px){.sa-summary{grid-template-columns:1fr 1fr}.sa-metric{padding:13px}.sa-metric strong{font-size:20px}.sa-head,.sa-body{padding:15px}}
