<?php if(!$ready): ?><div class="sa-note"><strong>Agreement tracking setup required.</strong> Import <code>database/sponsor_agreement_deliverables_migration.sql</code> before using this page.</div>
<?php else:
 $total=count($agreements);$deliverableCount=0;$completeCount=0;$overdueCount=0;$outstanding=0;foreach($agreements as $a){$aid=(int)$a['id'];$st=$conn->prepare("SELECT COUNT(*) total,SUM(status='fulfilled') fulfilled,SUM(status NOT IN ('fulfilled','waived') AND due_date<CURDATE()) overdue FROM sponsor_agreement_deliverables WHERE agreement_id=?");if($st){$st->bind_param('i',$aid);$st->execute();$r=$st->get_result()->fetch_assoc()?:[];$st->close();$deliverableCount+=(int)($r['total']??0);$completeCount+=(int)($r['fulfilled']??0);$overdueCount+=(int)($r['overdue']??0);$outstanding+=(int)($r['total']??0)-(int)($r['fulfilled']??0);}}
 ?>
 <div class="sa-summary"><div class="sa-metric"><small>Agreements</small><strong><?= $total ?></strong></div><div class="sa-metric"><small>Tracked deliverables</small><strong><?= $deliverableCount ?></strong></div><div class="sa-metric"><small>Fulfilled deliverables</small><strong><?= $completeCount ?></strong></div><div class="sa-metric"><small>Overdue commitments</small><strong><?= $overdueCount ?></strong></div></div>
 <div class="sa-note" style="margin-bottom:16px">This view reflects deliverables recorded against agreements linked to programmes assigned to your sponsor account. Verification status is shown separately from delivery status; an unverified completion is not presented as verified.</div>
