 <?php if(!$agreements): ?><div class="sa-empty">No published sponsorship agreements are currently available for your assigned programmes.</div><?php endif; ?>
 <?php foreach($agreements as $a): ?><a class="sa-agreement <?= $selected&&(int)$selected['id']===(int)$a['id']?'active':'' ?>" href="<?= url('sponsor/agreements.php?id='.(int)$a['id']) ?>"><strong><?= sponsor_e($a['title']) ?></strong><small><?= sponsor_e($a['agreement_ref']) ?> · <?= sponsor_e($a['programme_name']) ?></small><div class="sa-pills"><span class="sa-pill"><?= sponsor_e(sponsor_status((string)$a['status'])) ?></span><span class="sa-pill">Ends <?= sponsor_date($a['end_date']) ?></span></div></a><?php endforeach; ?>
 </div></section>
 <section class="sa-card"><div class="sa-head"><strong><?= $selected?sponsor_e($selected['title']):'Agreement deliverables' ?></strong><?php if($selected): ?><div style="font-size:11px;color:var(--muted);margin-top:5px"><?= sponsor_e($selected['agreement_ref']) ?> · <?= sponsor_e($selected['programme_name']) ?></div><?php endif; ?></div><div class="sa-body">
 <?php if(!$selected): ?><div class="sa-empty">Choose an agreement to view its contractual commitments, milestone due dates, progress and verification records.</div>
 <?php else: ?><p style="margin-top:0;color:var(--muted)"><?= nl2br(sponsor_e($selected['summary']??'')) ?></p><div class="sa-pills"><span class="sa-pill">Status: <?= sponsor_e(sponsor_status((string)$selected['status'])) ?></span><span class="sa-pill">Signed: <?= sponsor_date($selected['signed_on']) ?></span><span class="sa-pill">Period: <?= sponsor_date($selected['start_date']) ?> – <?= sponsor_date($selected['end_date']) ?></span><?php if($selected['agreement_value']!==null): ?><span class="sa-pill">Value: <?= sponsor_e($selected['currency']??'ZAR') ?> <?= number_format((float)$selected['agreement_value'],2) ?></span><?php endif; ?></div>
 <div class="sp-tablewrap" style="margin-top:18px"><table class="sa-table"><thead><tr><th>Deliverable / milestone</th><th>Due date</th><th>Progress</th><th>Delivery status</th><th>Verification</th><th>Evidence</th></tr></thead><tbody>
 <?php foreach($deliverables as $d): ?><tr><td><strong><?= sponsor_e($d['title']) ?></strong><div style="color:var(--muted);margin-top:4px"><?= sponsor_e($d['description']??'') ?></div><small style="color:var(--muted)"><?= sponsor_e($d['deliverable_ref']??'') ?></small></td><td><?= sponsor_date($d['due_date']) ?></td><td><span class="sa-value"><?= max(0,min(100,(int)$d['progress_percent'])) ?>%</span><div class="sa-progress"><span style="width:<?= max(0,min(100,(int)$d['progress_percent'])) ?>%"></span></div></td><td><?= sponsor_e(sponsor_status((string)$d['status'])) ?></td><td><?= sponsor_e(sponsor_status((string)$d['verification_status'])) ?><?php if($d['verified_at']): ?><small style="display:block;color:var(--muted)"><?= sponsor_date($d['verified_at']) ?></small><?php endif; ?></td><td><?= $d['evidence_reference']?sponsor_e($d['evidence_reference']):'—' ?></td></tr><?php endforeach; ?>
 <?php if(!$deliverables): ?><tr><td colspan="6">No deliverables have been recorded against this agreement yet.</td></tr><?php endif; ?></tbody></table></div>
 <div style="margin-top:14px;color:var(--muted);font-size:11px">Outstanding commitments include deliverables not marked fulfilled or waived. Contact your programme management team through Communications for clarification or follow-up.</div><?php endif; ?>
 </div></section></div>
<?php endif; ?>
